'use strict';
/* Four studios: presentation over the existing data, editor and XN Bridge. */
function uiRoute(route){return ({webnovel:'series',images:'prints',etsy:'prints',pinterest:'prints',ai:'settings',channels:'settings',prompts:'settings',tracking:'overview',metrics:'overview',calendar:'series',publish:'series'})[route]||route}
function uiTotals(month){const rows=db.metrics.filter(m=>String(m.date).slice(0,7)===month);const revenue=rows.reduce((n,m)=>n+Number(m.revenue||0),0),cost=rows.reduce((n,m)=>n+Number(m.cost||0),0);return {rows,revenue,cost,profit:revenue-cost}}
function uiRevenueType(m){const platform=db.channels.find(c=>c.id===m.channelId)?.platform;return platform==='Etsy'?'print':['Webnovel','Web truyện','Webtoon'].includes(platform)||db.series.some(s=>s.channelId===m.channelId)?'story':'other'}
function uiPage(items,page=0,size=3){const pages=Math.max(1,Math.ceil(items.length/size)),index=Math.min(Math.max(0,Number(page)||0),pages-1);return {items:items.slice(index*size,(index+1)*size),page:index,pages,total:items.length}}
function uiProjects(){return [...db.series.map(s=>({id:s.id,title:s.title,type:'story',label:'Xưởng Truyện'})),...(db.printProjects||[]).map(p=>({id:p.id,title:p.title,type:'print',label:'Xưởng In ấn'}))]}
function uiSplitText(text,limit=800){const out=[];for(let start=0;start<text.length;){let end=Math.min(start+limit,text.length);if(end<text.length){const cut=text.slice(start,end).lastIndexOf('\n');if(cut>limit/2)end=start+cut+1}out.push(text.slice(start,end));start=end}return out.length?out:['']}
function uiValidatePrintRecords(value){if(value.printProjects===undefined)return;if(!Array.isArray(value.printProjects))throw Error('Danh sách bộ sản phẩm sai.');const ids=new Set;for(const p of value.printProjects){if(!p||typeof p.id!=='string'||!/^[-\w]+$/.test(p.id)||ids.has(p.id)||typeof p.title!=='string'||!Array.isArray(p.references))throw Error('Dữ liệu bộ sản phẩm / references không hợp lệ.');ids.add(p.id);for(const r of p.references){if(!r||typeof r.id!=='string'||typeof r.title!=='string')throw Error('Mẫu tham khảo không hợp lệ.');if(r.data&&!/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(r.data))throw Error('Ảnh tham khảo không hợp lệ.');if(r.link&&!/^https?:\/\//i.test(r.link))throw Error('Link tham khảo không hợp lệ.')}}}
function uiLegacyItems(){const projects=db.printProjects||[],ids=new Set(projects.map(p=>p.id)),linked=new Set(projects.map(p=>p.etsyWorkflowId));return [...(db.assets||[]).filter(a=>!ids.has(a.printProjectId)).map(a=>({id:a.id,title:a.title,type:'asset'})),...(db.workflows||[]).filter(w=>!linked.has(w.id)).map(w=>({id:w.id,title:w.title,type:w.type}))]}
// UI runtime
const uiState={book:'',print:'',storyTab:'produce',printTab:'produce',month:today().slice(0,7),source:'all',pages:{},drafts:{},printDrafts:{},batchDrafts:{}};
const uiLabels={overview:'Tổng quan',series:'Xưởng Truyện',prints:'Xưởng In ấn',settings:'Cài đặt'};
const uiSVG={book:'M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3z M12 6v16',print:'M7 3h10v5H7z M7 16H4V8h16v8h-3 M7 13h10v8H7z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',money:'M5 20V9h3v11 M11 20V4h3v16 M17 20V12h3v8',coins:'M4 7c0-4 16-4 16 0s-16 4-16 0v5c0 4 16 4 16 0V7 M4 12v5c0 4 16 4 16 0v-5',trend:'M3 18l6-6 4 3 8-10 M15 5h6v6',folder:'M3 5h7l2 3h9v13H3z',plug:'M8 2v5 M16 2v5 M5 7h14v5a7 7 0 0 1-14 0z M12 19v3',bell:'M5 17V9a7 7 0 0 1 14 0v8l2 2H3z M10 22h4',image:'M3 3h18v18H3z M3 17l6-7 5 6 3-4 4 5 M16 7h1',info:'M12 8v1 M12 11v7 M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20',chevron:'M9 5l7 7-7 7',edit:'M4 16L16 4l4 4L8 20H4z'};
function uiIcon(name){return `<svg class="u-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${uiSVG[name]||uiSVG.folder}"/></svg>`}
function uiBadge(text,tone='muted'){return `<span class="u-badge ${tone}">${esc(text)}</span>`}
function uiPager(key,items,size=3){const p=uiPage(items,uiState.pages[key],size);return p.pages>1?`<div class="u-pagination"><button data-ui-page="${key}" data-direction="-1" ${p.page===0?'disabled':''}>‹ Trước</button><span>${p.page+1}/${p.pages}</span><button data-ui-page="${key}" data-direction="1" ${p.page===p.pages-1?'disabled':''}>Sau ›</button></div>`:''}
function uiHint(text){return `<div class="u-hint">${uiIcon('info')}<span>${text}</span></div>`}
function uiHeader(title,subtitle,extra=''){return `<div class="u-page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${extra}</div>`}
function uiChrome(route){$('#sidebar').innerHTML=`<a class="u-brand" href="#overview"><span class="u-logo">X</span><b>Xưởng Nội Dung</b></a><nav id="nav" aria-label="Điều hướng chính">${Object.entries(uiLabels).map(([id,label])=>`<a href="#${id}" ${route===id?'aria-current="page"':''}>${label}</a>`).join('')}</nav><div class="u-top-tools"><button class="u-icon-button" data-ui-action="activity" aria-label="Công việc cần xử lý">${uiIcon('bell')}</button><button class="u-avatar" data-ui-action="settings" aria-label="Mở cài đặt">X</button></div>`;document.title=(uiLabels[route]||'Công cụ')+' | Xưởng Nội Dung'}
function uiChart(rows){const year=Number(uiState.month.slice(0,4)),month=Number(uiState.month.slice(5)),days=new Date(year,month,0).getDate(),values=Array.from({length:days},(_,i)=>rows.filter(m=>Number(m.date.slice(8))===i+1).reduce((n,m)=>n+Number(m.revenue||0),0)),max=Math.max(1000,...values),width=830,height=150,pad=110;const coords=values.map((v,i)=>[pad+i*(width-pad-8)/(days-1),height-18-v/max*(height-35)]);return `<svg class="u-chart" viewBox="0 0 ${width} ${height+18}" role="img" aria-label="Doanh thu theo ngày, tháng ${esc(uiState.month)}">${[0,.25,.5,.75,1].map(v=>`<line x1="${pad}" x2="${width}" y1="${height-18-v*(height-35)}" y2="${height-18-v*(height-35)}" stroke="var(--u-line)"/><text x="${pad-8}" y="${height-14-v*(height-35)}" text-anchor="end">${num(Math.round(v*max))}</text>`).join('')}<path d="M${pad},${height-18} L${coords.map(p=>p.join(',')).join(' L')} L${width-8},${height-18}Z" fill="#e0f3e9"/><polyline points="${coords.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#159467" stroke-width="2"/>${coords.filter((_,i)=>i%2===0).map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="2.4" fill="#159467"/>`).join('')}${[1,8,15,22,days].map(n=>`<text x="${pad+(n-1)*(width-pad-8)/(days-1)}" y="${height+9}" text-anchor="${n===days?'end':n===1?'start':'middle'}">${String(n).padStart(2,'0')}/${String(month).padStart(2,'0')}</text>`).join('')}${!rows.length?`<text x="450" y="65" text-anchor="middle">Chưa có số liệu trong tháng</text>`:''}</svg>`}
function uiOverview(){const t=uiTotals(uiState.month),projects=uiProjects(),projectSize=innerHeight<=850?1:3,page=uiPage(projects,uiState.pages.projects,projectSize),byType=[['Xưởng Truyện','story'],['Xưởng In ấn','print'],...(t.rows.some(m=>uiRevenueType(m)==='other')?[['Nguồn khác','other']]:[])].map(([label,type])=>[label,t.rows.filter(m=>uiRevenueType(m)===type).reduce((n,m)=>n+Number(m.revenue||0),0)]);const filtered=uiState.source==='all'?t.rows:t.rows.filter(m=>uiRevenueType(m)===uiState.source);const waiting=db.content.filter(c=>c.status==='review').length;
return `<div class="u-overview">${uiHeader('Tổng quan','Doanh thu, tiến độ dự án và tình trạng vận hành',`<div class="u-actions"><input type="month" id="uMonth" aria-label="Tháng báo cáo" value="${esc(uiState.month)}"><button data-ui-action="report">Xem báo cáo</button></div>`)}<div class="u-kpis">${[['Doanh thu',money(t.revenue),'Theo số liệu đã nhập','money'],['Chi phí',money(t.cost),'Chi phí đã ghi nhận','coins'],['Lợi nhuận',money(t.profit),'Doanh thu trừ chi phí','trend'],['Dự án đang triển khai',projects.length+' dự án','Truyện và bộ sản phẩm','folder']].map(([label,value,note,ico],i)=>`<section class="u-card u-kpi"><span class="u-kpi-icon">${uiIcon(ico)}</span><div><p>${label}</p><strong class="${i===0||i===2?'u-green':''}">${value}</strong><small>${note}</small></div></section>`).join('')}</div><div class="u-overview-middle"><section class="u-card"><div class="u-card-head"><h2>Doanh thu trong tháng</h2><div class="u-segment">${[['all','Tất cả'],['story','Xưởng Truyện'],['print','Xưởng In ấn']].map(([id,label])=>`<button data-ui-source="${id}" class="${uiState.source===id?'selected':''}">${label}</button>`).join('')}</div></div>${uiChart(filtered)}</section><section class="u-card u-revenue-sources"><h2>Doanh thu theo xưởng</h2>${byType.map(([label,n])=>`<div><div class="u-spread"><span>${label}</span><strong>${money(n)}</strong></div><div class="u-bar-row"><span class="u-track"><i style="width:${t.revenue?n/t.revenue*100:0}%"></i></span><small>${t.revenue?(n/t.revenue*100).toFixed(1).replace('.',','):0}%</small></div></div>`).join('')}<small>Theo số liệu đã cập nhật</small></section></div><div class="u-overview-bottom"><section class="u-card"><div class="u-card-head"><h2>Dự án đang triển khai</h2>${uiPager('projects',projects,projectSize)}</div><table class="u-table"><thead><tr><th>Dự án</th><th>Công việc hiện tại</th><th>Tiến độ</th><th>Trạng thái</th><th></th></tr></thead><tbody>${page.items.map(p=>{const s=p.type==='story'?db.series.find(s=>s.id===p.id):null,chapters=s?lfChapters(s):[],approved=chapters.filter(c=>['approved','live'].includes(c.status)).length;return `<tr><td><strong>${esc(p.title)}</strong><small>${uiBadge(p.label,'green')}</small></td><td>${s?(lfApproved(s,'bible')?'Sản xuất chương':'Chuẩn bị cốt truyện'):'Chuẩn bị thiết kế'}</td><td><span class="u-track"><i style="width:${chapters.length?approved/chapters.length*100:0}%"></i></span><small>${s?approved+'/'+chapters.length+' chương':'Đang chuẩn bị'}</small></td><td>${uiBadge(s&&chapters.some(c=>c.status==='review')?'Cần bạn duyệt':'Đang triển khai',s&&chapters.some(c=>c.status==='review')?'amber':'blue')}</td><td><button class="u-text" data-ui-open="${p.id}" data-project-type="${p.type}">Mở dự án ›</button></td></tr>`}).join('')||'<tr><td colspan="5" class="u-empty">Chưa có dự án. Tạo bộ truyện hoặc bộ sản phẩm để bắt đầu.</td></tr>'}</tbody></table></section><section class="u-card"><h2>Tình trạng phần mềm</h2>${uiHealth()}<div class="u-spread u-card-foot"><small>Quản lý kết nối và phần mềm trong Cài đặt</small><button class="u-text" data-ui-action="settings">Mở cài đặt ›</button></div></section></div><div class="u-alert u-spread"><span>● &nbsp; Cần xử lý: ${waiting?waiting+' nội dung đang chờ duyệt':'Chưa có công việc chờ duyệt'}</span><button class="u-text" data-ui-action="activity">Xem công việc ›</button></div></div>`}
function uiHealth(){const state=bridgeConnectionState();return `<div class="u-health"><div><span>Web Xưởng</span><span class="u-dot green">Hoạt động</span></div><div><span>ChatGPT Bridge</span><span id="uBridgeHealth" class="u-dot ${state.tone==='connected'?'green':'red'}">${esc(state.label.replace(' — không nhận được Bridge',''))}</span></div><div><span>Tự động hóa in ấn</span><span class="u-dot muted">Chưa triển khai</span></div><div><span>Lưu dữ liệu</span><span class="u-dot ${loadError?'red':'green'}">${loadError?'Cần khôi phục':'Đã lưu trên trình duyệt'}</span></div></div>`}
function uiLibrary(type){const list=type==='story'?db.series:(db.printProjects||[]),selected=type==='story'?uiState.book:uiState.print,key=type==='story'?'books':'prints',p=uiPage(list,uiState.pages[key],4);return `<aside class="u-library"><h2>${type==='story'?'Bộ truyện của tôi':'Bộ sản phẩm của tôi'}</h2><button class="${type==='story'?'primary':''} u-wide" data-ui-action="${type==='story'?'new-book':'new-print'}">＋ Tạo ${type==='story'?'truyện mới':'bộ sản phẩm'}</button><div class="u-library-items">${p.items.map(item=>`<button class="u-library-item ${selected===item.id?'active':''}" data-ui-select="${item.id}" data-project-type="${type}"><span class="u-dot ${type==='story'&&lfApproved(item,'bible')?'green':'amber'}"></span><span><strong>${esc(item.title)}</strong><small>${type==='story'?`${lfChapters(item).length} chương · ${lfApproved(item,'bible')?'Đã duyệt cốt truyện':'Đang chuẩn bị'}`:(db.assets||[]).filter(a=>a.printProjectId===item.id).length+' thiết kế'}</small></span></button>`).join('')||'<p class="u-empty">Chưa có dự án.</p>'}</div>${uiPager(key,list,4)}${type==='print'&&uiLegacyItems().length?`<button data-ui-action="legacy-assets">Ảnh / sản phẩm hiện có (${uiLegacyItems().length})</button>`:''}${uiHint('Chọn '+(type==='story'?'truyện':'bộ sản phẩm')+' để sản xuất tiếp')}</aside>`}
function uiStory(){const books=db.series;if(!books.some(s=>s.id===uiState.book))uiState.book=books[0]?.id||'';const s=books.find(s=>s.id===uiState.book);return `<div class="u-workspace">${uiLibrary('story')}<div class="u-studio">${uiHeader('Xưởng Truyện','Từ ý tưởng đến bộ truyện hoàn chỉnh, sản xuất từng đợt chương.')}<div class="u-tabs"><button data-ui-storytab="produce" class="${uiState.storyTab==='produce'?'active':''}">Sản xuất truyện</button><button data-ui-storytab="publish" class="${uiState.storyTab==='publish'?'active':''}">Kết nối đăng truyện</button></div>${uiState.storyTab==='publish'?uiPublishing('story',s):s?uiStoryBook(s):`<section class="u-card u-start"><h2>Bắt đầu bộ truyện đầu tiên</h2><p>Nhập chủ đề hoặc script tham khảo. ChatGPT xây dựng cốt truyện và nhân vật để bạn duyệt.</p><button class="primary" data-ui-action="new-book">＋ Tạo truyện mới</button></section>`}</div></div>`}
function uiCurrentStage(s){const p=lfPipeline(s);if(p.source.mode==='reference'&&!lfApproved(s,'dna'))return ['dna','Content DNA','ANALYZE_REFERENCE_SCRIPT'];for(const [stage,label,kind]of [['concept','Concept','GENERATE_CONCEPT'],['bible','Cốt truyện tổng quan','GENERATE_STORY_BIBLE'],['characters','Nhân vật','GENERATE_CHARACTERS'],['outline','Dàn ý chương','GENERATE_OUTLINE']])if(!lfApproved(s,stage))return [stage,label,kind];return ['ready','Sẵn sàng viết chương','']}
function uiStoryBook(s){const sd=lfData(s),p=lfPipeline(s),bible=p.artifacts.bible?.value,chars=p.artifacts.characters?.value.characters||sd.characters,draft=uiState.drafts[s.id]||{},src={...p.source,...draft},stage=uiCurrentStage(s),jobs=(db.aiJobs||[]).filter(j=>j.seriesId===s.id&&j.storyTask),j=jobs.filter(j=>['queued','waiting_send','running','ready','error'].includes(j.status)).at(-1),n=lfNextChapter(s),batch={...s.uiBatch,...uiState.batchDrafts[s.id]};const step=stage[0]==='ready'?3:stage[0]==='dna'||stage[0]==='concept'?1:2;
return `<section class="u-card u-book-panel"><div class="u-card-head"><h2>${esc(s.title)}</h2>${uiBadge(lfApproved(s,'bible')?'Cốt truyện đã duyệt':'Đang xây dựng cốt truyện','green')}<button class="u-text" data-ui-action="chapters">Danh sách chương (${lfChapters(s).length}) ›</button></div><div class="u-steps">${['Ý tưởng & nguồn','Cốt truyện & nhân vật','Sản xuất chương'].map((label,i)=>`<span class="${i+1===step?'active':i+1<step?'complete':''}"><b>${i+1<step?'✓':i+1}</b>${i+1}. ${label}</span>`).join('')}</div><section class="u-section u-source"><div class="u-source-title"><h3>Ý tưởng & nguồn tham khảo</h3><button class="u-text u-edit-source" data-ui-action="edit-source">Chỉnh nguồn</button></div><div class="u-source-grid"><label>Ý tưởng chính của truyện<textarea data-ui-story-field="topic" placeholder="Chủ đề bạn muốn phát triển…">${esc(src.topic||'')}</textarea></label><div><label>Link truyện / YouTube tham khảo (tùy chọn)<input data-ui-story-field="referenceLink" placeholder="Dán link tham khảo…" value="${esc(src.referenceLink||'')}"></label><label>Câu lệnh văn phong cá nhân (tùy chọn)<textarea data-ui-story-field="options" placeholder="Để trống để ChatGPT tự đề xuất văn phong phù hợp">${esc(src.options||'')}</textarea></label></div></div><div class="u-spread"><div class="u-actions"><button data-ui-action="build-story">Xây dựng / cập nhật cốt truyện</button><button class="u-text" data-ui-action="reference-script">Dán script / transcript</button></div><small>Link tham khảo cần có nội dung nguồn để phân tích.</small></div></section><section class="u-section u-story-details"><div class="u-card-head"><h3>Cốt truyện & nhân vật</h3><button class="u-text" data-ui-action="edit-bible">✎ Chỉnh sửa</button></div><div class="u-detail-columns"><div><b>Cốt truyện tổng quan</b><p class="u-story-synopsis">${esc(bible?.premise||s.synopsis||'Chưa xây dựng cốt truyện. Nhập ý tưởng rồi bấm Xây dựng cốt truyện.')}</p><b>Twist & nút thắt</b><div class="u-twists">${(bible?.mainThreads||'Chưa có twist. AI sẽ đề xuất để bạn điều chỉnh.').split('\n').filter(Boolean).slice(0,2).map(x=>`<p>□ &nbsp;${esc(x)}</p>`).join('')}</div></div><div class="u-cast"><b>Nhân vật</b>${chars.slice(0,3).map((c,i)=>`<button class="u-character" data-ui-character="${esc(c.id||'character_'+i)}"><span class="u-initial color-${i%3}">${esc((c.name||c.title||'?').slice(0,1))}</span><span><strong>${esc(c.name||c.title)}</strong><small>${esc(c.role||'Nhân vật')}</small></span><small>${esc((c.goal||c.body||'').slice(0,90))}</small><span>✎</span></button>`).join('')||'<p class="u-empty">Nhân vật sẽ hiện sau khi AI xây dựng.</p>'}</div></div><div class="u-spread"><div class="u-alert">ⓘ &nbsp; Có thể bổ sung tình tiết giữa chừng; chương đã duyệt được giữ nguyên.</div><button data-ui-action="story-advanced">Điều chỉnh hướng truyện</button></div></section><section class="u-section u-batch"><h3>Sản xuất đợt tiếp theo</h3><small>Đã có ${lfChapters(s).length} chương · Đợt mới bắt đầu từ Chương ${n}</small><div class="u-batch-controls"><label>Số chương đợt này<input id="uChapterCount" type="number" min="1" max="30" value="${Number(batch?.count)||10}"></label><label>Hướng phát triển<select id="uEnding">${opts([['continue','Tiếp tục câu chuyện'],['open','Chuẩn bị kết mở'],['closed','Chuẩn bị kết đóng']],batch?.ending||'continue')}</select></label><button class="primary" data-ui-action="batch">Sản xuất đợt chương</button></div><label class="u-inline-label">Yêu cầu bổ sung cho đợt này<input id="uBatchOptions" value="${esc(batch?.options||'')}" placeholder="Ví dụ: đẩy mạnh xung đột giữa hai nhân vật…"></label><div class="u-suggestion">♧ &nbsp;${esc(batch?.start?`Đợt ${batch.start}–${batch.end}: ${batch.count} chương theo kế hoạch đã duyệt.`:'Gợi ý: phát triển nút thắt chưa giải quyết; giữ nhất quán với các chương đã duyệt.')}</div><small>Nội dung được tạo ở bản nháp và cần bạn duyệt trước khi đăng.</small></section>${uiStoryJob(s,stage,j)}</section>`}
function uiStoryJob(s,stage,j){if(j)return `<div class="u-job u-spread"><div><strong>${esc(lfJobKinds[j.storyTask]||'Công việc AI')}</strong><small>${esc(jobState(j))}${j.error?' · '+esc(j.error):''}</small></div><div class="u-actions">${j.status==='ready'?`<button class="primary" data-ui-apply="${j.id}">Xem và áp dụng kết quả</button>`:''}${j.resultText?`<button data-ui-result="${j.id}">Xem kết quả</button>`:''}${['ready','error','queued','waiting_send','running'].includes(j.status)?`<button data-ui-discard="${j.id}">Dừng / giữ kết quả</button>`:''}</div></div>`;const a=lfPipeline(s).artifacts[stage[0]];return stage[0]==='ready'||!a?'':`<div class="u-job u-spread"><span>Bước tiếp theo: <strong>${stage[1]}</strong> · ${a?'Cần bạn duyệt':'Chưa triển khai'}</span><div class="u-actions">${a?'<button data-ui-action="review-stage">Xem / chỉnh kết quả</button><button class="primary" data-ui-action="approve-stage">Duyệt và tiếp tục</button>':'<button class="primary" data-ui-action="build-story">Tạo bằng ChatGPT</button>'}</div></div>`}
function uiPrint(){const list=db.printProjects||[];if(!list.some(p=>p.id===uiState.print))uiState.print=list[0]?.id||'';const p=list.find(p=>p.id===uiState.print);return `<div class="u-workspace">${uiLibrary('print')}<div class="u-studio">${uiHeader('Xưởng In ấn','Tìm ý tưởng, tạo thiết kế và chuẩn bị sản phẩm đăng Etsy.')}<div class="u-tabs"><button data-ui-printtab="produce" class="${uiState.printTab==='produce'?'active':''}">Sản xuất thiết kế</button><button data-ui-printtab="publish" class="${uiState.printTab==='publish'?'active':''}">Kết nối đăng bán</button></div>${uiState.printTab==='publish'?uiPublishing('print',p):p?uiPrintProject(p):`<section class="u-card u-start"><h2>Bắt đầu bộ sản phẩm đầu tiên</h2><p>Thêm mẫu tham khảo, chọn phong cách và chuẩn bị thiết kế gốc.</p><button class="primary" data-ui-action="new-print">＋ Tạo bộ sản phẩm</button></section>`}</div></div>`}
function uiPrintProject(project){const p={...project,...uiState.printDrafts[project.id]},refs=p.references||[],assets=db.assets.filter(a=>a.printProjectId===p.id),approved=assets.filter(a=>a.approval==='approved'&&a.data),page=uiPage(assets,uiState.pages.designs,3),refpage=uiPage(refs,uiState.pages.references,4),workflow=db.workflows.find(w=>w.id===p.etsyWorkflowId);return `<section class="u-card u-print-panel"><div class="u-card-head"><h2>${esc(p.title)}</h2>${uiBadge('Đang chuẩn bị','green')}<span class="u-spacer"></span>${uiBadge('Tự động hóa: Chờ tích hợp')}</div><div class="u-steps"><span class="complete"><b>✓</b>1. Tìm ý tưởng</span><span class="active"><b>2</b>2. Tạo thiết kế</span><span><b>3</b>3. Chuẩn bị đăng Etsy</span></div><section class="u-section"><h3>Nguồn tham khảo & định hướng</h3><div class="u-source-grid"><div><label>Chủ đề / từ khóa<input data-ui-print-field="keyword" value="${esc(p.keyword||'')}" placeholder="Sản phẩm muốn phát triển…"></label><p>Nguồn tham khảo</p><div class="u-checks">${['Pinterest','Google','Etsy'].map(n=>`<label><input type="checkbox" data-ui-print-source="${n}" ${(p.sources||[]).includes(n)?'checked':''}>${n}</label>`).join('')}</div><button disabled title="Tự động tìm sản phẩm chưa được tích hợp">Tìm sản phẩm tham khảo</button> ${uiBadge('Chờ tích hợp')}<small>Có thể dán link hoặc thêm ảnh tham khảo thủ công.</small></div><div><label>Phong cách thiết kế<textarea data-ui-print-field="style" placeholder="Màu sắc, bố cục, phong cách…">${esc(p.style||'')}</textarea></label><div class="u-three-fields"><label>Sản phẩm<select data-ui-print-field="productType">${opts(['Áo thun','Poster','Sản phẩm số','Khác'],p.productType||'Áo thun')}</select></label><label>Số thiết kế<input data-ui-print-field="count" type="number" min="1" max="100" value="${Number(p.count)||12}"></label><label>Đầu ra<select data-ui-print-field="output">${opts(['PNG nền trong','PNG','JPEG'],p.output||'PNG nền trong')}</select></label></div></div></div></section><section class="u-section u-references"><div class="u-card-head"><h3>Ý tưởng & mẫu tham khảo</h3><span class="u-spacer"></span>${uiPager('references',refs,4)}<button class="u-text" data-ui-action="add-reference">＋ Thêm ảnh / link</button></div><div class="u-reference-grid">${refpage.items.length?refpage.items.map(ref=>`<button class="u-reference" data-ui-reference="${ref.id}">${ref.data?`<img src="${esc(ref.data)}" alt="${esc(ref.title)}">`:`<span class="u-placeholder">${uiIcon('image')}</span>`}<small>${esc(ref.title||ref.source||'Tham khảo')}</small></button>`).join(''):Array.from({length:4},()=>`<button class="u-reference" data-ui-action="add-reference"><span class="u-placeholder">${uiIcon('image')}<span>Thêm mẫu tham khảo</span></span><small>Ảnh / link của bạn</small></button>`).join('')}</div><small>Tham khảo xu hướng để tạo thiết kế gốc; không sao chép mẫu.</small></section><div class="u-print-bottom"><section class="u-section"><div class="u-card-head"><h3>Thiết kế đang sản xuất</h3><small>${assets.filter(a=>a.data).length}/${Number(p.count)||12} thiết kế đã tạo · ${approved.length} đã duyệt</small></div><div class="u-design-grid">${page.items.length?page.items.map((a,i)=>`<button data-workflow="asset" data-wid="${a.id}" class="u-design">${a.data?`<img src="${a.data}" alt="${esc(a.title)}">`:`<span class="u-placeholder">${uiIcon('image')}<span>Chưa có ảnh</span></span>`}<small>${esc(a.title)} · ${uiBadge(a.approval==='approved'?'Đã duyệt':'Chờ duyệt',a.approval==='approved'?'green':'amber')}</small></button>`).join(''):Array.from({length:3},(_,i)=>`<button class="u-design" data-ui-action="new-design"><span class="u-placeholder">${uiIcon('image')}</span><small>Mẫu ${String(i+1).padStart(2,'0')} · Chưa có ảnh</small></button>`).join('')}</div><div class="u-spread"><div class="u-actions"><button class="primary" data-ui-action="new-design">Tạo đợt thiết kế</button><button data-ui-action="upload-design">Nhập ảnh</button></div>${uiPager('designs',assets,3)}</div><small>Thiết kế mới luôn chờ bạn duyệt.</small></section><section class="u-section u-etsy-prep"><h3>Chuẩn bị sản phẩm Etsy</h3>${[['Ảnh sản phẩm',approved.length+' ảnh đã duyệt',approved.length?'green':'muted'],['Tiêu đề & mô tả',workflow?.description?'Bản nháp':'Chưa tạo','blue'],['13 thẻ tag',workflow?.tags?'Đã chuẩn bị':'Chưa tạo','amber'],['Giá & loại sản phẩm',workflow?.price?'Đã thiết lập':'Chưa thiết lập','red']].map(([label,status,tone])=>`<button class="u-check-row" data-ui-action="etsy-draft"><span>${uiIcon('image')}${label}</span>${uiBadge(status,tone)}<span>›</span></button>`).join('')}<button class="u-wide" data-ui-action="etsy-draft">Mở bản nháp sản phẩm</button><div class="u-hint u-spread"><small>Tự động đăng / hẹn giờ: Chưa tích hợp</small><button class="u-text" data-ui-printtab="publish">Xem kết nối đăng bán ›</button></div></section></div></section>`}
function uiBridgeDetails(){const state=bridgeConnectionState(),present=!!bridgeStatus.ok,connected=present&&bridgeStatus.connected,last=(db.aiJobs||[]).filter(j=>j.resultText&&['ready','applied'].includes(j.status)).at(-1);return `<div class="u-card-head"><span class="u-kpi-icon">${uiIcon('plug')}</span><div><h2>ChatGPT Bridge</h2><p>Sản xuất nội dung và hình ảnh qua ChatGPT Plus.</p></div><span class="u-spacer"></span>${uiBadge(state.label.replace(' — không nhận được Bridge',''),state.tone==='connected'?'green':state.tone==='checking'?'amber':'red')}</div><div class="u-diagnostic">${[['Extension trên trình duyệt',present?'Đã nhận Bridge':'Chưa nhận được Bridge',present?'green':'red',present?'Bridge '+esc(bridgeStatus.version||'')+' phản hồi.':'Chưa phát hiện extension trong trang này.'],['Tab ChatGPT',connected?'Đã chọn tab':'Chưa xác nhận',connected?'green':'muted',connected?esc(bridgeStatus.conversation?.title||'ChatGPT'):'Chưa xác nhận đã chọn tab ChatGPT.'],['Gửi / nhận kết quả',last?'Đã nhận kết quả':'Chưa kiểm tra',last?'green':'muted',last?'Có kết quả được lưu trong Xưởng.':'Chưa kiểm tra khả năng gửi / nhận kết quả.']].map(([label,status,tone,help])=>`<div><strong>${label}</strong>${uiBadge(status,tone)}<small>${help}</small></div>`).join('')}</div><small>Phiên bản hỗ trợ: 0.4.0 &nbsp; | &nbsp; Không dùng API key</small>`}
function uiSettings(){return `<div class="u-settings">${uiHeader('Cài đặt','Kết nối công cụ và quản lý dữ liệu cho toàn bộ Xưởng.')}<p class="u-settings-note">Dùng chung cho Xưởng Truyện và Xưởng In ấn.</p><div class="u-settings-grid"><div class="u-settings-left"><section class="u-card u-bridge-card"><div id="uBridgeSettings">${uiBridgeDetails()}</div><div class="u-actions"><button class="primary" data-ui-action="bridge-check">Kiểm tra kết nối</button><a class="u-button" href="/downloads/" target="_blank" rel="noopener">Tải Bridge 0.4.0</a><button class="u-text" data-ui-action="bridge-help">Hướng dẫn cài / cập nhật</button></div><div class="u-setup"><strong>Kết nối lần đầu</strong><ol><li>Cài Bridge trong Chrome hoặc Edge</li><li>Chọn tab ChatGPT trong popup extension</li><li>Tải lại Xưởng và kiểm tra kết nối</li></ol><p class="u-blue">ⓘ Nếu mở Xưởng trong khung ChatGPT, hãy thử mở bằng tab trình duyệt riêng.</p></div><div class="u-setup u-package-note"><p><b>Gói ZIP:</b> 1 thư mục Xuong_ChatGPT_Bridge</p><p><b>Cập nhật:</b> ghi đè file trong thư mục đã cài → Tải lại extension.</p></div></section><section class="u-card u-common"><h2>${uiIcon('settings')} Cách vận hành chung</h2><div class="u-common-fields"><label>Ngôn ngữ giao diện<select aria-label="Ngôn ngữ giao diện"><option>Tiếng Việt</option></select></label><label>Giao diện<span class="u-segment"><button data-ui-theme="light" class="${!document.documentElement.classList.contains('dark')?'selected':''}">Sáng</button><button data-ui-theme="dark" class="${document.documentElement.classList.contains('dark')?'selected':''}">Tối</button></span></label><div><span>Lưu thay đổi</span><p class="u-dot ${loadError?'red':'green'}">${loadError?'Cần khôi phục':'Tự động trên trình duyệt'}</p></div></div><div class="u-rule green"><b>♙ Duyệt trước khi đăng</b><span>Luôn bật</span><small>Truyện, hình ảnh và sản phẩm đều cần bạn duyệt.</small></div><div class="u-rule"><b>◷ Khi kết nối bị gián đoạn</b><span>Giữ công việc để tiếp tục</span><small>Không tự tạo lại nội dung đã có kết quả.</small></div></section></div><div class="u-settings-right"><section class="u-card"><h2>${uiIcon('settings')} Phần mềm tự động hóa</h2><div class="u-integration"><div><strong>Claude Code / Bộ tự động hóa</strong><small>Tìm ý tưởng sản phẩm, chuẩn bị và đăng Etsy.</small></div>${uiBadge('Chưa tích hợp')}</div><div class="u-integration"><div><strong>Phần mềm khác</strong><small>Kết nối thêm công cụ khi được hỗ trợ.</small></div>${uiBadge('Chưa cấu hình')}</div><button data-ui-action="software">Xem cấu hình kết nối</button>${uiHint('Chỉ hiển thị Đã kết nối sau khi công cụ phản hồi.')}</section><section class="u-card"><h2>${uiIcon('coins')} Lưu trữ & sao lưu</h2><div class="u-settings-row"><strong>Nơi lưu dữ liệu</strong><span>Trình duyệt hiện tại</span></div><div class="u-settings-row"><strong>Yêu cầu xuất gần nhất</strong>${uiBadge(db.uiSettings?.lastBackupAt?dateText(db.uiSettings.lastBackupAt):'Chưa có bản sao lưu',db.uiSettings?.lastBackupAt?'green':'amber')}</div><p>Chưa có đồng bộ giữa các thiết bị.</p><div class="u-actions"><button data-ui-action="backup">Xuất bản sao lưu</button><button data-ui-action="restore">Khôi phục dữ liệu</button><button class="u-text" data-ui-action="csv">Xuất CSV</button></div><small>Sao lưu trước khi đổi trình duyệt hoặc thiết bị.</small></section><section class="u-card"><h2>${uiIcon('info')} Thông tin & cập nhật</h2><div class="u-settings-row"><span>Phiên bản web</span><span>0.5.0</span></div><div class="u-settings-row"><span>Gói Bridge hiện tại</span><span>0.4.0</span></div><div class="u-actions u-right"><button class="u-text" data-ui-action="updates">Xem lịch sử cập nhật</button><button class="u-text" data-ui-action="bug">Báo lỗi</button><button class="u-text" data-ui-action="tools">Công cụ khác</button></div></section></div></div>${uiHint('Tài khoản đăng truyện và cửa hàng Etsy được quản lý tại Kết nối đăng truyện / Kết nối đăng bán trong từng Xưởng.')}</div>`}
function uiPublishing(type,project){const channels=db.channels.filter(c=>type==='print'?c.platform==='Etsy':['Webnovel','Web truyện','Webtoon'].includes(c.platform)),chapters=project&&type==='story'?lfChapters(project):[],p=uiPage(chapters,uiState.pages.publish,5);return `<section class="u-card u-publishing"><div class="u-card-head"><h2>${type==='story'?'Kênh đăng truyện':'Cửa hàng Etsy'}</h2>${uiPager(type+'Channels',channels,2)}<button data-new="channels">＋ Thêm kênh</button></div>${uiHint('Đăng tự động qua API chưa được tích hợp. Lịch bên dưới là lịch nội bộ; bạn xác nhận sau khi đăng trên nền tảng.')}<div class="u-channel-grid">${uiPage(channels,uiState.pages[type+'Channels'],2).items.map(c=>`<article class="u-section"><strong>${esc(c.name)}</strong>${uiBadge('Đăng thủ công','amber')}<p>${esc(c.platform)}</p><div class="u-actions"><button data-edit="channels" data-id="${c.id}">Chỉnh sửa kênh</button>${safeLink(c.adminUrl||c.link,'Mở nền tảng')}</div></article>`).join('')||'<p class="u-empty">Chưa có kênh. Thêm kênh để chuẩn bị lịch đăng.</p>'}</div><div class="u-card-head"><h3>${project?esc(project.title):'Lịch nội dung'}</h3>${type==='story'&&project?'<button data-ui-action="schedule">Xếp lịch chương đã duyệt</button>':''}${uiPager('publish',chapters,5)}</div><table class="u-table"><thead><tr><th>Nội dung</th><th>Trạng thái</th><th>Thời gian dự kiến</th><th>Thao tác</th></tr></thead><tbody>${p.items.map(c=>`<tr><td>${esc(c.title)}</td><td>${esc(statuses[c.status])}</td><td>${dateText(c.scheduledAt)}</td><td><button data-edit="content" data-id="${c.id}">Mở chương</button></td></tr>`).join('')||`<tr><td colspan="4" class="u-empty">${type==='print'?'Mở bản nháp sản phẩm trong Sản xuất thiết kế để chuẩn bị nội dung.':'Chương và lịch đăng của bộ truyện sẽ xuất hiện tại đây.'}</td></tr>`}</tbody></table></section>`}
function uiRender(){const route=uiRoute(view);if(!uiLabels[route]){uiLegacyRender();uiChrome('');document.body.classList.add('u-legacy');return}document.body.classList.remove('u-legacy');document.body.classList.add('u-app');view=route;uiChrome(route);$('#main').innerHTML=({overview:uiOverview,series:uiStory,prints:uiPrint,settings:uiSettings})[route]();uiCompactPanels(route);$('#main').dataset.screen=route;$('#breadcrumb').textContent='Xưởng Nội Dung / '+uiLabels[route]}
async function uiTools(){const d=await choose('Công cụ hiện có',select('tool','Chọn công cụ',[['channels','Kênh'],['prompts','Thư viện câu lệnh'],['content','Nội dung'],['metrics','Số liệu'],['asset','Hình ảnh']], 'channels'));if(!d)return;if(d.tool==='asset'){openWorkflow('asset');return}const type=d.tool;await uiReadDocument(`<div class="u-spread"><h3>Dữ liệu hiện có</h3><button data-new="${type}">＋ Thêm mới</button></div>`+(db[type]||[]).map(row=>`<article class="u-chapter-row"><strong>${esc(row.title||row.name||row.date||row.id)}</strong><button data-edit="${type}" data-id="${row.id}">Mở / sửa</button>${type==='prompts'?`<button data-preview="${row.id}">Dùng câu lệnh</button>`:''}</article>`).join(''),'Công cụ hiện có')}
function uiCompactPanels(route){if(innerHeight>850)return;if(route==='settings'){const grid=document.querySelector('.u-settings-grid'),left=grid.children[0],right=grid.children[1];uiState.compact??={};const selected=uiState.compact.settings||0,nav=document.createElement('div');nav.className='u-segment u-settings-pages';nav.innerHTML=['Kết nối công cụ','Dữ liệu & vận hành'].map((label,i)=>`<button class="${i===selected?'selected':''}" data-ui-panel="settings" data-panel-index="${i}">${label}</button>`).join('');grid.before(nav);left.children[0].hidden=selected!==0;left.children[1].hidden=selected!==1;right.children[0].hidden=selected!==0;right.children[1].hidden=selected!==1;right.children[2].hidden=selected!==1;grid.classList.add('u-compact-settings');return}if(!['series','prints'].includes(route))return;const panel=document.querySelector(route==='series'?'.u-book-panel':'.u-print-panel');if(!panel)return;const items=route==='series'?[...panel.querySelectorAll(':scope>.u-section')]:[...panel.children].filter(el=>el.matches('.u-section,.u-print-bottom')),labels=route==='series'?['Ý tưởng & nguồn','Cốt truyện & nhân vật','Đợt chương']:['Nguồn & phong cách','Mẫu tham khảo','Thiết kế & Etsy'];uiState.compact??={};const selected=Math.min(uiState.compact[route]||0,items.length-1),nav=document.createElement('div');nav.className='u-panel-pages u-segment';nav.innerHTML=items.map((el,i)=>`<button class="${i===selected?'selected':''}" data-ui-panel="${route}" data-panel-index="${i}">${labels[i]}</button>`).join('');panel.children[1].after(nav);panel.classList.add('u-compact-panel');items.forEach((el,i)=>{el.hidden=i!==selected;el.classList.add('u-panel-page')})}
function uiPersist(fn){const before=JSON.stringify(db);try{fn();if(!save())throw Error('Không lưu được thay đổi.')}catch(e){db=JSON.parse(before);throw e}}
function uiSelectedBook(){return db.series.find(s=>s.id===uiState.book)}
function uiSelectedPrint(){return db.printProjects.find(p=>p.id===uiState.print)}
function uiFlushBook(){const s=uiSelectedBook(),draft=uiState.drafts[s?.id];if(!s||!draft)return;const current=lfPipeline(s).source,next={...current,...draft};if(JSON.stringify(current)!==JSON.stringify(next))uiPersist(()=>lfSetSource(s,next));delete uiState.drafts[s.id]}
function uiFlushPrint(){const p=uiSelectedPrint(),draft=uiState.printDrafts[p?.id];if(p&&draft)uiPersist(()=>Object.assign(p,draft));delete uiState.printDrafts[p?.id]}
async function uiNewBook(){const d=await choose('Tạo truyện mới',input('title','Tên làm việc','','text','required')+input('topic','Chủ đề / ý tưởng','','textarea')+input('genre','Thể loại',''));if(!d)return;const c=findWebnovelChannel();if(!c)throw Error('Thêm kênh Webnovel trong Kết nối đăng truyện trước.');const s={id:uid(),title:d.title.trim(),channelId:c.id,chapterLength:1500,exclusivity:'Không độc quyền',genre:d.genre};lfSetSource(s,{mode:'topic',topic:d.topic.trim()||d.title.trim(),genre:d.genre,chapters:10,options:''});uiPersist(()=>db.series.push(s));uiState.book=s.id;uiState.pages.books=Math.floor((db.series.length-1)/4);view='series';location.hash='series';uiRender()}
async function uiBuildStory(s){uiFlushBook();const [stage,,kind]=uiCurrentStage(s);if(stage==='ready'){if(!await uiConfirm('Tạo lại concept sẽ cần duyệt lại các phần phụ thuộc. Chương đã duyệt vẫn được giữ. Tiếp tục?'))return;return await lfSend(s,'GENERATE_CONCEPT')}const artifact=lfPipeline(s).artifacts[stage];if(artifact&&artifact.dependency===lfDependency(s,stage))return uiReviewStage(s,stage);if(stage==='dna'){const next=lfNextDNA(s);if(next.complete){lfArtifact(s,'dna',next.value);save();return}await lfSend(s,kind,next.scope)}else await lfSend(s,kind)}
async function uiReviewStage(s,stage){const a=lfPipeline(s).artifacts[stage];if(!a)throw Error('Chưa có kết quả để duyệt.');const labels={title:'Tên truyện',logline:'Logline',premise:'Cốt truyện tổng quan',mainThreads:'Twist & nút thắt',originalityNotes:'Điểm khác biệt',world:'Thế giới',worldRules:'Quy tắc thế giới'};const text=Object.entries(a.value).map(([k,v])=>`<p><b>${esc(labels[k]||k)}</b></p><p>${esc(typeof v==='string'?v:JSON.stringify(v,null,2))}</p>`).join('');await uiReadDocument(text,stage==='bible'?'Cốt truyện tổng quan':stage==='characters'?'Nhân vật':'Kết quả để duyệt')}
async function uiReadDocument(html,title='Nội dung'){const pending=choose(title,`<div class="u-reader">${html}</div>`);const reader=$('#pickerFields .u-reader');let split=false;for(const child of [...reader.children])if(['PRE','P'].includes(child.tagName)&&child.textContent.length>800){const nodes=uiSplitText(child.textContent).map(part=>{const node=document.createElement(child.tagName);node.textContent=part;return node});child.replaceWith(...nodes);split=true}uiPaginateContainer(reader,split||reader.querySelector('pre')?1:4);await pending}
async function uiEditBible(s){const a=lfPipeline(s).artifacts.bible;if(!a){toast('Xây dựng cốt truyện trước để chỉnh sửa.');return}const d=await choose('Điều chỉnh cốt truyện',input('title','Tên truyện',a.value.title)+input('premise','Cốt truyện tổng quan',a.value.premise,'textarea')+input('mainThreads','Twist & nút thắt',a.value.mainThreads,'textarea'));if(!d)return;const value={...a.value,...d};lfValidateOutput(s,'GENERATE_STORY_BIBLE',value);uiPersist(()=>lfArtifact(s,'bible',value))}
async function uiReference(s){const p=lfPipeline(s),d=await choose('Script / transcript tham khảo',input('script','Dán nội dung nguồn (link chỉ dùng để lưu tham khảo)',p.source.script||'','textarea','rows="12"'));if(!d)return;uiFlushBook();uiPersist(()=>lfSetSource(s,{...p.source,mode:d.script.trim()?'reference':'topic',script:d.script}));toast('Đã lưu nguồn. Script dài được chia theo mạch nội dung.')}
async function uiBatch(s){uiFlushBook();if(!lfApproved(s,'outline'))throw Error('Duyệt cốt truyện, nhân vật và dàn ý trước khi viết chương.');const count=Number($('#uChapterCount').value);if(!Number.isInteger(count)||count<1||count>30)throw Error('Mỗi đợt từ 1 đến 30 chương.');const next=lfNextChapter(s);uiPersist(()=>s.uiBatch={id:uid(),start:next,end:next+count-1,count,ending:$('#uEnding').value,options:$('#uBatchOptions').value,status:'preparing'});if(!lfPlans(s,next).some(p=>p.kind==='chapter')){await lfSend(s,'GENERATE_OUTLINE',{extendTo:next+count-1,preserveExisting:true});toast('Đã yêu cầu mở rộng dàn ý. Bạn duyệt kế hoạch mới trước khi viết.');return}const defaults=lfChapterDefaults(s),ending={continue:'Tiếp tục phát triển câu chuyện.',open:'Chuẩn bị kết mở, giải quyết xung đột trung tâm nhưng giữ khả năng tiếp nối.',closed:'Chuẩn bị kết đóng trọn vẹn, giải quyết các nút thắt bằng sự kiện thực sự.'}[s.uiBatch.ending];defaults.prompt+='\n'+ending+'\n'+s.uiBatch.options;openEditor('content','',defaults);toast('Đã chuẩn bị đợt chương. Viết và duyệt từng chương để giữ đúng ngữ cảnh.')}
async function uiNewPrint(){const d=await choose('Tạo bộ sản phẩm',input('title','Tên bộ sản phẩm','','text','required')+input('keyword','Chủ đề / từ khóa','')+select('productType','Loại sản phẩm',['Áo thun','Poster','Sản phẩm số','Khác'],'Áo thun'));if(!d)return;const p={...d,id:uid(),style:'',count:12,output:'PNG nền trong',sources:['Pinterest','Google','Etsy'],references:[]};uiPersist(()=>db.printProjects.push(p));uiState.print=p.id;uiState.pages.prints=Math.floor((db.printProjects.length-1)/4);view='prints';location.hash='prints';uiRender()}
async function uiAddReference(p){uiFlushPrint();const d=await choose('Thêm mẫu tham khảo',input('title','Tên mẫu','','text','required')+input('link','Link tham khảo','','url')+'<p>Để thêm ảnh từ máy, chọn Nhập ảnh tham khảo ở bước sau.</p>'+select('mode','Cách thêm',[['link','Lưu link'],['image','Nhập ảnh tham khảo']],'link'));if(!d)return;if(d.mode==='image')return uiImportImage(p,'reference',d.title,d.link);if(!d.link)throw Error('Nhập link tham khảo.');if(!/^https?:\/\//i.test(d.link))throw Error('Link phải là http hoặc https.');uiPersist(()=>p.references.push({id:uid(),title:d.title,link:d.link,source:new URL(d.link).hostname}));}
function uiImportImage(p,type,title='',link=''){const file=document.createElement('input');file.type='file';file.accept='image/png,image/jpeg,image/webp';file.onchange=async()=>{const f=file.files[0];if(!f)return;try{if(f.size>5*1024*1024||!['image/png','image/jpeg','image/webp'].includes(f.type))throw Error('Chọn ảnh PNG, JPEG hoặc WebP tối đa 5 MB.');const data=await new Promise((resolve,reject)=>{const r=new FileReader;r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Không đọc được ảnh.'));r.readAsDataURL(f)});uiPersist(()=>{if(type==='reference')p.references.push({id:uid(),title:title||f.name,link,data,source:'Ảnh của bạn'});else db.assets.push({id:uid(),printProjectId:p.id,title:title||f.name,approval:'draft',data,ratio:'1:1',prompt:p.style||'',createdAt:new Date().toISOString()})});uiRender()}catch(e){toast(e.message)}};file.click()}
async function uiNewDesign(p){uiFlushPrint();const d=await choose('Tạo đợt thiết kế',input('count','Số thiết kế (tạo từng ảnh qua Bridge)',1,'number','min="1" max="30"')+input('prompt','Yêu cầu cho đợt này',p.style||'','textarea'));if(!d)return;const count=Number(d.count);if(!Number.isInteger(count)||count<1||count>30)throw Error('Số thiết kế từ 1 đến 30.');const assets=Array.from({length:count},(_,i)=>({id:uid(),title:p.title+' — Mẫu '+(db.assets.filter(a=>a.printProjectId===p.id).length+i+1),printProjectId:p.id,approval:'draft',ratio:'1:1',prompt:[p.keyword,d.prompt,'Create an original printable design. '+p.output].join('\n'),globalStyle:d.prompt,scenePrompt:p.keyword,createdAt:new Date().toISOString()}));uiPersist(()=>db.assets.push(...assets));uiRender();openWorkflow('asset',assets[0].id);}
async function uiEtsyDraft(p){uiFlushPrint();let c=db.channels.find(c=>c.platform==='Etsy');if(!c){if(!await uiConfirm('Chưa có kênh Etsy. Tạo kênh Etsy để lưu bản nháp sản phẩm?'))return;uiPersist(()=>{c={id:uid(),name:'Etsy',platform:'Etsy',link:'https://www.etsy.com/',style:'',visual:''};db.channels.push(c)})}let w=db.workflows.find(w=>w.id===p.etsyWorkflowId);if(!w){const a=db.assets.find(a=>a.printProjectId===p.id&&a.approval==='approved');w={id:uid(),title:p.title,channelId:c.id,type:'etsy',status:'draft',description:'',tags:'',currency:'USD',price:'',imageId:a?.id||'',createdAt:new Date().toISOString()};uiPersist(()=>{db.workflows.push(w);p.etsyWorkflowId=w.id})}openWorkflow('etsy',w.id)}
async function uiRestore(){const d=await choose('Khôi phục dữ liệu',input('json','Dán JSON bản sao lưu','','textarea','rows="12"')+'<p>Khôi phục thay thế dữ liệu hiện tại. Hãy xuất bản sao lưu trước.</p>');if(!d)return;const next=JSON.parse(d.json);validate(next);uiValidatePrintRecords(next);if(!await uiConfirm('Thay thế dữ liệu hiện tại bằng bản sao lưu này?'))return;const before=db,beforeError=loadError;db=next;loadError=false;db.assets??=[];db.workflows??=[];db.aiJobs??=[];db.printProjects??=[];if(!save()){db=before;loadError=beforeError;return}uiState.book='';uiState.print='';uiState.drafts={};uiState.printDrafts={};uiState.batchDrafts={};uiState.pages={};toast('Đã khôi phục dữ liệu.')}
async function uiActivity(){const rows=db.content.filter(c=>c.status==='review'),jobs=(db.aiJobs||[]).filter(j=>['ready','error','waiting_send','running'].includes(j.status));await uiReadDocument(`<h3>Nội dung chờ duyệt (${rows.length})</h3>${rows.map(c=>`<p>${esc(c.title)} <button data-edit="content" data-id="${c.id}">Mở</button></p>`).join('')||'<p>Không có nội dung chờ duyệt.</p>'}<h3>Công việc AI (${jobs.length})</h3>${jobs.map(j=>`<p>${esc(j.title)} — ${esc(jobState(j))} ${j.resultText?`<button data-ui-result="${j.id}">Xem kết quả</button>`:''}</p>`).join('')}`,'Công việc cần xử lý')}
