async function uiSchedule(s){const list=lfChapters(s).filter(c=>c.status==='approved');if(!list.length)throw Error('Chưa có chương đã duyệt để xếp lịch.');const d=await choose('Lịch đăng nội bộ',select('chapterId','Chương đã duyệt',list.map(c=>[c.id,c.title]),list[0].id)+input('scheduledAt','Thời gian dự kiến','','datetime-local','required'));if(!d)return;const c=list.find(c=>c.id===d.chapterId);uiPersist(()=>{c.scheduledAt=d.scheduledAt;c.updatedAt=new Date().toISOString()});toast('Đã lưu lịch nội bộ; không tự đăng lên nền tảng.')}
function uiPaginateContainer(container,size=4){if(!container)return;if(container.nextElementSibling?.classList.contains('u-dialog-pages'))container.nextElementSibling.remove();const children=[...container.children].filter(el=>el.tagName!=='INPUT'||el.type!=='hidden');if(children.length<=size)return;let index=0;const max=Math.ceil(children.length/size),pager=document.createElement('div');pager.className='u-dialog-pages';pager.innerHTML='<button type="button">‹ Trước</button><span></span><button type="button">Sau ›</button>';container.after(pager);const update=()=>{children.forEach((el,i)=>el.hidden=Math.floor(i/size)!==index);pager.children[0].disabled=index===0;pager.children[2].disabled=index===max-1;pager.children[1].textContent=(index+1)+' / '+max};container.addEventListener('invalid',e=>{const child=children.find(el=>el===e.target||el.contains(e.target));if(child){index=Math.floor(children.indexOf(child)/size);update()}},true);pager.children[0].onclick=()=>{index--;update()};pager.children[2].onclick=()=>{index++;update()};update()}
