document.addEventListener('input',e=>{const el=e.target;if(['uChapterCount','uBatchOptions','uEnding'].includes(el.id)){const s=uiSelectedBook();if(s)(uiState.batchDrafts[s.id]??={})[({uChapterCount:'count',uBatchOptions:'options',uEnding:'ending'})[el.id]]=el.id==='uChapterCount'?Number(el.value):el.value}if(el.dataset.uiStoryField){const s=uiSelectedBook();if(s)(uiState.drafts[s.id]??={})[el.dataset.uiStoryField]=el.value}if(el.dataset.uiPrintField){const p=uiSelectedPrint();if(p)(uiState.printDrafts[p.id]??={})[el.dataset.uiPrintField]=el.dataset.uiPrintField==='count'?Number(el.value):el.value}});
document.addEventListener('change',e=>{if(e.target.id==='uEnding'){const s=uiSelectedBook();if(s)(uiState.batchDrafts[s.id]??={}).ending=e.target.value}if(e.target.id==='uMonth'){uiState.month=e.target.value;uiRender()}if(e.target.dataset.uiPrintSource){const p=uiSelectedPrint();if(p){const draft=uiState.printDrafts[p.id]??={},set=new Set(draft.sources||p.sources||[]);e.target.checked?set.add(e.target.dataset.uiPrintSource):set.delete(e.target.dataset.uiPrintSource);draft.sources=[...set]}}});
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;const isUI=Object.keys(b.dataset).some(k=>k.startsWith('ui'))||b.matches('#nav a');if(!isUI)return;e.preventDefault();e.stopImmediatePropagation();try{if(b.matches('#nav a')){uiFlushBook();uiFlushPrint();location.hash=b.getAttribute('href');return}const s=uiSelectedBook(),p=uiSelectedPrint();if(b.dataset.uiPage){uiState.pages[b.dataset.uiPage]=Math.max(0,(uiState.pages[b.dataset.uiPage]||0)+Number(b.dataset.direction));return uiRender()}if(b.dataset.uiPanel){uiState.compact??={};uiState.compact[b.dataset.uiPanel]=Number(b.dataset.panelIndex);return uiRender()}if(b.dataset.uiSource){uiState.source=b.dataset.uiSource;return uiRender()}if(b.dataset.uiSelect){uiFlushBook();uiFlushPrint();if(b.dataset.projectType==='story')uiState.book=b.dataset.uiSelect;else uiState.print=b.dataset.uiSelect;return uiRender()}if(b.dataset.uiOpen){if(b.dataset.projectType==='story'){uiState.book=b.dataset.uiOpen;location.hash='series'}else{uiState.print=b.dataset.uiOpen;location.hash='prints'}return uiRender()}if(b.dataset.uiStorytab){uiFlushBook();uiState.storyTab=b.dataset.uiStorytab;return uiRender()}if(b.dataset.uiPrinttab){uiFlushPrint();uiState.printTab=b.dataset.uiPrinttab;return uiRender()}if(b.dataset.uiTheme){document.documentElement.classList.toggle('dark',b.dataset.uiTheme==='dark');localStorage.setItem('xuong-theme',b.dataset.uiTheme);return uiRender()}if(b.dataset.uiApply){const j=db.aiJobs.find(j=>j.id===b.dataset.uiApply);if(!j||j.status!=='ready')throw Error('Kết quả chưa sẵn sàng.');await uiReadDocument('<pre>'+esc(j.resultText)+'</pre>','Kiểm tra kết quả trước khi áp dụng');if(!await uiConfirm('Áp dụng vào đúng giai đoạn để chờ bạn duyệt?'))return;uiPersist(()=>{if(j.storyTask==='WRITE_CHAPTER'){const c=db.content.find(c=>c.id===j.targetId);applyStory(j,c)}else lfApplyTask(j,j.resultText)});return uiRender()}if(b.dataset.uiResult){const j=db.aiJobs.find(j=>j.id===b.dataset.uiResult);return await uiReadDocument('<pre>'+esc(j?.resultText||'')+'</pre>','Kết quả ChatGPT')}if(b.dataset.uiDiscard){const j=db.aiJobs.find(j=>j.id===b.dataset.uiDiscard);if(['waiting_send','running','queued'].includes(j.status)){const r=await bridgeCall('XN_CANCEL',{},5000);if(!r?.ok)throw Error('Chưa dừng được Bridge.')}uiPersist(()=>j.status='stopped');return uiRender()}if(b.dataset.uiCharacter){const chars=lfData(s).characters;if(!chars.some(c=>c.id===b.dataset.uiCharacter)){await uiReviewStage(s,'characters');return}await lfEditChar(s,b.dataset.uiCharacter);$('#longformDialog')?.close();return uiRender()}if(b.dataset.uiRevision){const c=db.content.find(c=>c.id===b.dataset.uiRevision);openEditor('content','',lfChapterDefaults(s,c));return}if(b.dataset.uiApproveMemory){const c=db.content.find(c=>c.id===b.dataset.uiApproveMemory);await uiReadDocument('<pre>'+esc(JSON.stringify(lfData(s).memoryDrafts?.[c.id]?.value,null,2))+'</pre>','Kiểm tra memory đề xuất');if(!await uiConfirm('Duyệt memory đã đối chiếu với chương?'))return;uiPersist(()=>lfApproveMemory(s,c));return uiRender()}if(b.dataset.uiMemory){await lfSend(s,'UPDATE_STORY_MEMORY',{chapterId:b.dataset.uiMemory});return uiRender()}if(b.dataset.uiReference){const ref=p.references.find(r=>r.id===b.dataset.uiReference);await uiReadDocument((ref.data?`<img class="u-reference-full" src="${esc(ref.data)}" alt="${esc(ref.title)}">`:'')+`<h3>${esc(ref.title)}</h3>`+safeLink(ref.link,'Mở nguồn tham khảo'),'Mẫu tham khảo');return}if(b.dataset.uiAdopt){const asset=db.assets.find(a=>a.id===b.dataset.uiAdopt);if(!p)throw Error('Tạo hoặc chọn bộ sản phẩm trước.');uiPersist(()=>asset.printProjectId=p.id);toast('Đã thêm ảnh vào bộ sản phẩm, giữ nguyên bản gốc.');return uiRender()}const action=b.dataset.uiAction;if(action==='settings'){location.hash='settings';return}if(action==='new-book')await uiNewBook();if(action==='new-print')await uiNewPrint();if(action==='legacy-assets')await uiReadDocument(uiLegacyItems().map(item=>`<article class="u-chapter-row"><strong>${esc(item.title)}</strong><button data-workflow="${item.type}" data-wid="${item.id}">Mở</button>${item.type==='asset'&&p?`<button data-ui-adopt="${item.id}">Thêm vào bộ sản phẩm</button>`:''}</article>`).join(''),'Ảnh và sản phẩm hiện có');if(action==='report')await uiReport();if(action==='activity')await uiActivity();if(action==='build-story'&&s)await uiBuildStory(s);if(action==='edit-source'&&s){const src={...lfPipeline(s).source,...uiState.drafts[s.id]},d=await choose('Ý tưởng và nguồn',input('topic','Ý tưởng chính',src.topic||'','textarea')+input('referenceLink','Link tham khảo',src.referenceLink||'')+input('options','Văn phong cá nhân',src.options||'','textarea'));if(d){uiState.drafts[s.id]={...uiState.drafts[s.id],...d};uiFlushBook()}}if(action==='reference-script'&&s)await uiReference(s);if(action==='edit-bible'&&s)await uiEditBible(s);if(action==='approve-stage'&&s){uiPersist(()=>lfApprove(s,uiCurrentStage(s)[0]));toast('Đã duyệt giai đoạn. Bấm tạo bước tiếp theo khi sẵn sàng.')}if(action==='review-stage'&&s)await uiReviewStage(s,uiCurrentStage(s)[0]);if(action==='story-advanced'&&s){uiFlushBook();lfDialog(s);return}if(action==='batch'&&s)await uiBatch(s);if(action==='chapters'&&s)await uiChapterList(s);if(action==='schedule'&&s)await uiSchedule(s);if(action==='add-reference'&&p)await uiAddReference(p);if(action==='new-design'&&p)await uiNewDesign(p);if(action==='upload-design'&&p)uiImportImage(p,'design');if(action==='etsy-draft'&&p)await uiEtsyDraft(p);if(action==='bridge-check'){await refreshBridge();await receiveResults()}if(action==='bridge-help')await uiReadDocument('<h3>Cài đặt và cập nhật Bridge</h3><p>ZIP chứa một thư mục Xuong_ChatGPT_Bridge. Chọn thư mục có manifest.json khi cài lần đầu.</p><p>Cập nhật: ghi đè file trong đúng thư mục đã cài, bấm Tải lại ở extension, rồi F5 Xưởng và ChatGPT.</p><p>Dùng cùng Chrome/Edge và profile, chọn tab trong popup. Nếu mở trong khung ChatGPT, thử tab riêng.</p><a href="/downloads/" target="_blank" rel="noopener">Mở trang tải và hướng dẫn</a>','Hướng dẫn Bridge');if(action==='software')await uiReadDocument('<p>Tự động tìm sản phẩm và đăng Etsy chưa được tích hợp. Chỉ cấu hình sau khi có bộ tự động hóa thực tế phản hồi.</p>','Kết nối phần mềm');if(action==='backup'){backup();uiPersist(()=>{db.uiSettings??={};db.uiSettings.lastBackupAt=new Date().toISOString()})}if(action==='restore')await uiRestore();if(action==='csv'){const rows=[['Ngày','Kênh','Nguồn','Doanh thu','Chi phí'],...db.metrics.map(m=>[m.date,channelName(m.channelId),m.source,m.revenue,m.cost||0])];download('xuong-doanh-thu.csv','\ufeff'+rows.map(row=>row.map(v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n'),'text/csv;charset=utf-8')}if(action==='updates')await uiReadDocument('<p>0.5.0: Giao diện bốn Xưởng, dữ liệu và cơ chế duyệt được giữ lại.</p><p>Bridge 0.4.0: ZIP một thư mục, hướng dẫn cập nhật tại chỗ.</p>','Lịch sử cập nhật');if(action==='bug')await uiReadDocument('<p>Ghi tên màn hình, thao tác gây lỗi, thời điểm và thông báo. Chụp ảnh có thanh trạng thái rồi gửi trong cuộc trò chuyện hỗ trợ.</p>','Báo lỗi');if(action==='tools'){await uiTools();return}uiRender()}catch(error){toast(error.message)}},true);
// Avoid losing typed inputs when the browser leaves the page; switching projects also flushes them.
window.addEventListener('beforeunload',()=>{try{uiFlushBook();uiFlushPrint()}catch{}});
window.addEventListener('hashchange',()=>{try{uiFlushBook();uiFlushPrint()}catch(e){toast(e.message)}});
uiRender();
